from .core import BASE, SITE, UPDATED, breadcrumb, faq, page, quick_answer, takeaways


def build():
    path='/en/labs/context-compression/'
    target=SITE/'en/labs/context-compression'
    target.mkdir(parents=True,exist_ok=True)
    title='Context Compression Lab — Keep the right information | AhaFrame'
    desc='Compress a simulated support-agent working context while balancing token savings, evidence retention, task quality, hallucination risk, latency, and cost.'
    schema={
        '@context':'https://schema.org',
        '@graph':[
            {'@type':'WebPage','@id':BASE+path+'#webpage','url':BASE+path,'name':'Context Compression Lab','description':desc,'inLanguage':'en','dateModified':UPDATED,'mainEntity':{'@id':BASE+path+'#learning-resource'}},
            {'@type':'LearningResource','@id':BASE+path+'#learning-resource','name':'Context Compression Lab','description':desc,'url':BASE+path,'inLanguage':'en','educationalLevel':'Intermediate','learningResourceType':'Interactive simulation','timeRequired':'PT25M','isAccessibleForFree':True,'publisher':{'@id':BASE+'/#organization'}},
        ],
    }
    body=f'''<div class="container"><div class="breadcrumb"><a href="/en/">Home</a> / Production Labs / Context Compression Lab</div><section class="lesson-hero"><div class="lesson-title-row"><div class="lesson-icon">▱</div><div><h1>Context Compression Lab</h1><div class="badges"><span class="badge level">Production Lab Preview</span><span class="badge">Intermediate</span><span class="badge">25 min</span></div><p class="lede">The support agent is cheap and fast because the context was compressed aggressively. The hidden failure: it no longer remembers enough policy, account state, and order evidence to make a reliable refund decision.</p></div></div><div class="lesson-tools"><button type="button" class="btn small" data-share>Share</button></div></section>{quick_answer('Context compression is not a contest to minimize tokens; a defensible policy removes low-value context while preserving the instructions and evidence that determine the task outcome.')}
    <div data-context-compression-lab><section class="card interactive"><div class="panel-title"><span>Over-compressed support-agent context</span><span class="badge">Deterministic simulation</span></div><p class="subtle">The original working set contains 25,500 synthetic tokens. Production allows a 16,000-token working context. Start from a policy that saves more than two thirds of the tokens, then find out what those savings removed.</p><div class="lab-control-grid" style="display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:18px"><div><label class="label" for="context-compression-ratio">Compression ratio</label><div class="control-row"><input id="context-compression-ratio" class="slider" type="range" min="20" max="85" step="1" value="72"><output class="badge" data-context-compression-ratio-value>72%</output></div><label class="label" for="context-summary-depth" style="display:block;margin-top:18px">Summary depth</label><select id="context-summary-depth" class="select" style="margin-top:8px"><option value="shallow">Shallow summary</option><option value="balanced">Balanced summary</option><option value="deep">Deep summary</option></select><label class="label" for="context-retrieval-budget" style="display:block;margin-top:18px">Retrieved evidence budget</label><div class="control-row"><input id="context-retrieval-budget" class="slider" type="range" min="800" max="4200" step="200" value="1600"><output class="badge" data-context-retrieval-budget-value>1,600 tokens</output></div></div><div><label class="label" for="context-memory-budget">Long-term memory budget</label><div class="control-row"><input id="context-memory-budget" class="slider" type="range" min="0" max="3000" step="300" value="600"><output class="badge" data-context-memory-budget-value>600 tokens</output></div><button type="button" class="btn wide" data-context-protect-critical style="margin-top:16px">Critical facts: UNPROTECTED</button><div class="note" style="margin-top:16px"><strong>Production constraint:</strong> active context must fit inside 16,000 tokens. Critical information includes the task, safety policy, account eligibility, refund policy, and retrieved order evidence.</div><div class="actions" style="margin-top:16px"><button type="button" class="btn primary" data-context-balanced-preset>Apply balanced policy</button><button type="button" class="btn" data-context-compression-reset>Reset over-compressed baseline</button></div></div></div></section>
    <section class="card lesson-section" style="padding:20px;margin-top:18px"><div class="panel-title"><span>Working-context outcome</span><span class="badge" data-context-budget-status>Calculating…</span></div><div class="metrics" style="margin-top:14px"><div class="metric">Active context<br><strong data-context-active-tokens>—</strong></div><div class="metric">Token savings<br><strong data-context-savings>—</strong></div><div class="metric">Critical retention<br><strong data-context-critical-retention>—</strong></div><div class="metric">Evidence coverage<br><strong data-context-evidence-coverage>—</strong></div><div class="metric">Task quality<br><strong data-context-task-quality>—</strong></div><div class="metric">Hallucination risk<br><strong data-context-hallucination-risk>—</strong></div><div class="metric">Latency index<br><strong data-context-latency-index>—</strong></div><div class="metric">Cost index<br><strong data-context-cost-index>—</strong></div></div><div class="note" style="margin-top:14px"><strong>Current diagnosis:</strong> <span data-context-compression-diagnosis>Calculating…</span></div></section>
    <section class="card lesson-section" style="padding:20px;margin-top:18px"><div class="panel-title"><span>What survived compression?</span><span class="badge">Synthetic working set</span></div><p class="subtle">Token retention and semantic retention are not identical. A deeper summary can preserve more useful meaning per retained token, while a retrieval or memory budget can still exclude information before summarization gets a chance to protect it.</p><div style="overflow-x:auto;margin-top:12px"><table class="feature-matrix eval-table"><thead><tr><th>Context segment</th><th>Original tokens</th><th>Active tokens</th><th>Semantic retention</th></tr></thead><tbody data-context-segments></tbody></table></div></section>
    <section class="card lesson-section" style="padding:20px;margin-top:18px"><div class="panel-title">Compression trade-off</div><div class="compare-grid" style="margin-top:14px"><div class="compare-card warn"><span class="label">Baseline policy</span><strong>Very cheap · very lossy</strong><p class="subtle">The initial policy aggressively minimizes the working context and silently discards task-critical information.</p></div><span class="flow-arrow">→</span><div class="compare-card good"><span class="label">Your current policy</span><div data-context-compression-compare style="display:grid;gap:6px;margin-top:6px"><span>Waiting for changes…</span></div></div></div></section></div>
    {takeaways([('Compression has a semantic budget','Saving tokens is useful only when the remaining representation preserves the instructions and evidence the task depends on.'),('Protect critical facts before optimizing averages','A small safety or eligibility detail can matter more than thousands of background tokens.'),('Retrieval budget is an admission decision','A summarizer cannot preserve evidence that retrieval never admitted into the working context.'),('More context is not automatically safer','Keeping everything can exceed the runtime budget and reintroduce latency and cost even when quality is excellent.'),('The defensible point is usually in the middle','Good context engineering trades some information density for cost while keeping critical retention above the task-specific floor.')])}
    <section class="card section-explainer"><span class="eyebrow">Context Engineering</span><h2>Why can a shorter context make an AI system worse even when the summary sounds correct?</h2><p>A language model does not receive the original application state directly. It receives a constructed working context: instructions, the user request, retrieved evidence, memory, tool observations, and background material. Compression changes that constructed environment. A fluent summary can therefore sound reasonable while omitting the one account flag, policy exception, or prior promise that changes the correct action.</p><h3>Compression ratio is only the visible knob</h3><p>Teams often discuss compression as a percentage: reduce the context by 50%, 70%, or 80%. That number is not enough. Two policies with the same token count can preserve very different information depending on which segments were summarized, what the retrieval layer admitted, and which facts were protected from lossy transformation.</p><h3>Critical facts deserve a different policy from background context</h3><p>In this scenario, the system and safety policy, current task, account eligibility, refund policy, and order evidence are marked critical. Turning on critical-fact protection reserves more of their representation before less important conversation history and product background. This is a simplified model of a common production pattern: classify information by consequence before applying a generic compressor.</p><h3>Retrieval and memory budgets happen before generation</h3><p>A low retrieval budget can starve the model of evidence even when the compression policy protects critical facts. The missing evidence cannot be recovered by a better prompt or a deeper summary because it never entered the context. Memory has a similar trade-off: too little can remove useful continuity, while too much can crowd the working set with stale or weakly relevant history.</p><h3>Why does the Lab include a 16k budget?</h3><p>Without a hard capacity constraint, the easiest way to maximize simulated quality would be to retain nearly everything. Real systems have context limits, latency targets, and unit economics. The 16,000-token budget makes the opposite failure visible: an under-compressed policy may retain perfect information but still be operationally invalid.</p><h3>What is simulated here?</h3><p>All token counts, semantic-retention values, quality scores, hallucination-risk values, latency indexes, and cost indexes are deterministic educational quantities. They are not measurements from a live model, tokenizer, summarizer, retrieval system, or customer-support workload. Production thresholds must be established with representative tasks, real model behavior, and evaluation evidence.</p><h3>Common questions</h3>{faq([('Should I always protect every fact marked critical?','Protecting consequential instructions and evidence is a strong default, but real systems still need task-specific classification, freshness rules, and conflict resolution.'),('Does a deeper summary always improve the system?','No. It can preserve more meaning but also consumes more tokens and processing. The right depth depends on the task and budget.'),('Why not just increase the context window?','A larger model context can reduce immediate truncation pressure, but it does not remove retrieval quality, stale memory, latency, attention allocation, or cost trade-offs.'),('Is context compression the same as prompt compression?','Prompt compression is one technique inside a broader context-engineering problem. The working context also includes retrieval, memory, tool state, conversation history, and application-owned instructions.')])}<div class="references"><strong>AhaFrame simulation note</strong> · Reviewed {UPDATED}. Values are synthetic and designed to make context-selection trade-offs visible; they are not universal production thresholds.</div></section>
    <section class="card build-card" data-context-compression-build><div><span class="eyebrow">Build challenge</span><h3>Define a context policy for a refund-capable support agent.</h3><p>Choose what must survive compression, how much evidence retrieval can admit, how much memory is worth carrying, and where you would set the context budget. Explain which information you are willing to lose and which information must be release-blocking if absent.</p></div><a class="btn" data-event="context_compression_build_challenge_started" href="/en/early-access/?intent=context-compression-build-challenge">Take the challenge →</a></section>
    <section class="card next-band"><div><strong>You balanced information against cost.</strong><div class="subtle">Next, the Reliable Support Agent Build will connect retrieval, context policy, bounded execution, human approval, and evaluation gates into one production architecture decision.</div></div><a class="btn primary" data-event="context_compression_paid_intent_click" href="/en/early-access/?intent=reliable-support-agent-build">Continue to the capstone →</a></section></div>'''
    scripts='<script src="/assets/context-compression-scenario.js" defer></script><script src="/assets/context-compression.js" defer></script>'
    (target/'index.html').write_text(page(title,desc,path,body,active='Lessons',schemas=[schema,breadcrumb([('AhaFrame','/en/'),('Production Labs','/en/#production-labs'),('Context Compression Lab',path)])],scripts=scripts),encoding='utf-8')
